import type { Metadata } from 'next'

export const SITE_NAME = 'Shriraj Naik'
export const SITE_TITLE = 'Shriraj Naik — QA Automation Engineer & AI Product Engineer'
export const SITE_DESCRIPTION =
  'QA automation engineer with 4+ years in FinTech testing, who also builds and ships full-stack AI products. Case studies, experience and resume.'

/** Generated by `pnpm assets:build` (scripts/assets). */
const SOCIAL_IMAGE = {
  url: '/og.png',
  width: 1200,
  height: 630,
  alt: 'Shriraj Naik, QA Automation Engineer & AI Product Engineer',
}

/**
 * Open Graph and Twitter tags for one page. Next.js replaces a parent's `openGraph` and `twitter`
 * objects (it doesn't merge them) when a page sets its own, so every page takes the full set from here.
 */
export function socialMetadata(page: {
  title: string
  description: string
  path: string
  type: 'website' | 'article'
}): Pick<Metadata, 'openGraph' | 'twitter'> {
  const { title, description, path, type } = page
  return {
    openGraph: { type, url: path, siteName: SITE_NAME, title, description, locale: 'en_IN', images: [SOCIAL_IMAGE] },
    twitter: { card: 'summary_large_image', title, description, images: [SOCIAL_IMAGE.url] },
  }
}
